<script setup lang="ts">
import {valueAt,withValue,blockThumbnail} from '~/shared/cms/page-editors.mjs'
import {cmsDate,changedItems} from '~/shared/cms/workflow.mjs'
import {resourceGuide,editingSchema} from '~/shared/cms/presentation.mjs'
const props=defineProps<{id:string}>()
const route=useRoute(),router=useRouter(),{api,session,message}=useCmsAdmin()
const {data:namedPages}=useNuxtData<any[]>('cms-pages')
const pageData=ref<any>(),docs=ref<any[]>([]),bodies=ref<Record<string,any>>({}),baseline=ref<Record<string,any>>({}),error=ref(''),notice=ref(''),busy=ref(false),fieldErrors=ref<any[]>([]),selections=ref<Record<string,string>>({}),locationOpen=ref(false),formRoot=ref<HTMLElement>()
provide('cms-field-errors',fieldErrors);provide('cms-item-selections',selections)
const blocks=computed<any[]>(()=>{const named=namedPages.value?.find(p=>p.id===props.id);return(pageData.value?.blocks||[]).map((b:any)=>({...b,name:named?.blocks.find((n:any)=>n.id===b.id)?.name||b.name}))})
provide('cms-select-block',(name:string)=>{const block=blocks.value.find(b=>b.name===name);if(block)void selectBlock(block.id)})
const active=computed(()=>blocks.value.find(b=>b.id===route.query.block)||blocks.value[0])
const title=computed(()=>namedPages.value?.find(p=>p.id===props.id)?.title||pageData.value?.title||'修改頁面')
const modified=computed(()=>blocks.value.filter(b=>b.fields.some((f:any)=>JSON.stringify(valueAt(bodies.value[f.documentId],f.path))!==JSON.stringify(valueAt(baseline.value[f.documentId],f.path)))))
const dirty=computed(()=>modified.value.length>0),pending=computed(()=>docs.value.some(d=>d.draftId!==d.publishedId))
const status=computed(()=>dirty.value?`尚未儲存 · ${modified.value.length} 處修改`:pending.value?'已儲存，官網尚未更新':'官網已更新')
const impacts=computed<any[]>(()=>[...new Map(docs.value.flatMap(d=>resourceGuide(d.id)?.impacts||[]).map(i=>[i.href+'|'+i.label,i])).values()])
const shared=computed(()=>{const ids=new Set(modified.value.flatMap(b=>b.fields.filter((f:any)=>JSON.stringify(valueAt(bodies.value[f.documentId],f.path))!==JSON.stringify(valueAt(baseline.value[f.documentId],f.path))).map((f:any)=>f.documentId)));return impacts.value.filter(i=>docs.value.some(d=>ids.has(d.id)&&resourceGuide(d.id)?.impacts?.some((j:any)=>j.href===i.href))&&i.href.split('#')[0]!==pageData.value?.href.split('#')[0])})
const returnLink=computed(()=>{const {sitePage,block,edit,part,legacy,field,item,returnPath,returnSection,...query}=route.query;if(typeof returnSection==='string')query.section=returnSection;return{path:returnPath==='/admin/content'?'/admin/content':props.id==='home'?'/admin':'/admin/content',query}})
const activeDocs=computed(()=>docs.value.filter(d=>active.value?.fields.some((f:any)=>f.documentId===d.id)))
const payload=(action:string)=>({action,documents:docs.value.map(d=>({id:d.id,revision:d.revision,body:bodies.value[d.id]}))})
async function selectBlock(id:string){locationOpen.value=false;await router.replace({query:{...route.query,block:id,legacy:undefined,field:undefined}});await nextTick();formRoot.value?.querySelector<HTMLElement>('.cms-block-title')?.focus()}
function update(f:any,value:any){bodies.value={...bodies.value,[f.documentId]:withValue(bodies.value[f.documentId],f.path,value)}}
async function load(){error.value='';try{const result=await api('page-editors/'+props.id,{timeout:20000,retry:0});if(!Array.isArray(result?.documents)||!Array.isArray(result?.blocks))throw Error('伺服器未回傳完整頁面內容，請確認連線後重試。');pageData.value=result;docs.value=result.documents;bodies.value=Object.fromEntries(result.documents.map((d:any)=>[d.id,d.body]));baseline.value=JSON.parse(JSON.stringify(bodies.value));if(route.query.legacy){const b=result.blocks.find((b:any)=>b.fields.some((f:any)=>f.documentId===route.query.legacy));if(b)await router.replace({query:{...route.query,block:b.id,legacy:undefined}})}}catch(e){error.value=message(e)}}
async function focusError(){const issue=fieldErrors.value[0];if(!issue)return;const block=blocks.value.find(b=>b.fields.some((f:any)=>f.documentId===issue.documentId&&(issue.path===f.path||issue.path.startsWith(f.path+'.'))));if(block)await selectBlock(block.id);await nextTick();formRoot.value?.querySelector<HTMLElement>('[aria-invalid=true]')?.focus()}
function reload(){if(!dirty.value||window.confirm('重新載入會捨棄本頁尚未儲存的修改，確定繼續？'))void load()}

const previewOpen=ref(false),previewReady=ref(false),previewResult=ref<any>(null),previewError=ref(''),previewState=ref(''),mobile=ref(false),previewPath=ref(''),initialToken=ref(''),previewFrame=ref<HTMLIFrameElement>(),previewSize=ref({width:480,height:640})
let timer:ReturnType<typeof setTimeout>|undefined,previewTimer:ReturnType<typeof setTimeout>|undefined,sequence=0,needsReload=false,recovery=0,controller:AbortController|undefined,observer:ResizeObserver|undefined
const previewScale=computed(()=>Math.min(1,previewSize.value.width/(mobile.value?390:1440)))
const frameStyle=computed(()=>({width:(mobile.value?390:1440)+'px',height:previewSize.value.height/(previewScale.value||1)+'px',transform:`scale(${previewScale.value})`}))
const previewUrl=computed(()=>{const [path,anchor]=(previewPath.value||active.value?.href||pageData.value?.href||'/').split('#');return`${path}${path.includes('?')?'&':'?'}cmsPreview=page:${encodeURIComponent(props.id)}&cmsDraft=${encodeURIComponent(initialToken.value)}${anchor?'#'+anchor:''}`})
const choices=computed(()=>docs.value.flatMap(d=>{
 const b=bodies.value[d.id],items=d.id==='data-kitchenSeries'?b?.KITCHEN_SERIES_PAGES:d.id==='data-storeCases'?b?.storeCases:['custom-cases','knowledge-articles','news-articles'].includes(d.id)?b?.items:[]
 return(items||[]).filter((i:any)=>!pageData.value?.category||i.summary?.category===pageData.value.category).map((i:any)=>({label:i.summary?.title||i.title||i.name||i.slug,path:d.id==='news-articles'?`/news/${i.summary.category}/${i.slug}`:d.id==='knowledge-articles'?`/knowledge/design/${i.slug}`:d.id==='data-kitchenSeries'?`/home-style/${i.slug}`:d.id==='data-storeCases'?`/gallery/${i.slug}`:`/design-inspiration/${i.id}`}))
}))
watch(previewFrame,frame=>{observer?.disconnect();if(frame?.parentElement){observer=new ResizeObserver(([entry])=>{if(entry)previewSize.value={width:entry.contentRect.width,height:entry.contentRect.height}});observer.observe(frame.parentElement)}},{flush:'post'})
function failPreview(reason:string){clearTimeout(previewTimer);previewReady.value=false;needsReload=true;previewError.value=reason;previewState.value='目前輸入尚未套用，可重試或返回修改'}
function sendPreview(){if(!previewOpen.value||!previewReady.value||!previewResult.value||needsReload)return;previewState.value='正在更新效果…';previewFrame.value?.contentWindow?.postMessage(JSON.parse(JSON.stringify({type:'sakura:preview',documents:previewResult.value.documents,previewToken:previewResult.value.previewToken})),location.origin);clearTimeout(previewTimer);previewTimer=setTimeout(()=>failPreview('官網預覽沒有回應，請重新載入；目前輸入仍保留。'),20000)}
function receive(event:MessageEvent){if(!previewOpen.value||event.origin!==location.origin||event.source!==previewFrame.value?.contentWindow)return
 if(event.data?.type==='sakura:ready'){previewReady.value=true;if(previewResult.value?.documents.length!==docs.value.length||!previewResult.value.documents.every((d:any)=>JSON.stringify(d.body)===JSON.stringify(bodies.value[d.id])))return;needsReload=false;sendPreview()}
 if(event.data?.type==='sakura:applied'&&!needsReload&&event.data.previewToken===previewResult.value?.previewToken){clearTimeout(previewTimer);previewState.value='目前輸入的效果・尚未更新官網';previewError.value='';recovery=0}
 if(event.data?.type==='sakura:preview-error'&&!needsReload){failPreview(event.data.message||'預覽載入失敗。');if(event.data.statusCode===404&&event.data.previewExpired&&recovery<1){recovery++;void reloadPreview(false)}}
}
async function checkPreview(show=previewOpen.value){
 if(!docs.value.length)return
 controller?.abort();controller=new AbortController();const n=++sequence,snapshot=JSON.stringify(payload('preview'));if(show)previewState.value='正在準備目前輸入…'
 try{const r=await api('page-editors/'+props.id,{method:'POST',body:payload('preview'),timeout:20000,retry:0,signal:controller.signal});if(n!==sequence||snapshot!==JSON.stringify(payload('preview')))return;if(!Array.isArray(r?.documents)||typeof r?.previewToken!=='string')throw Error('官網效果未收到完整回應，請確認連線後重試；目前輸入仍保留。');fieldErrors.value=[];if(show&&previewOpen.value){previewResult.value=r;previewError.value='';if(!initialToken.value||needsReload||!previewReady.value){needsReload=false;previewReady.value=false;initialToken.value=r.previewToken;previewState.value='正在載入官網畫面…';clearTimeout(previewTimer);previewTimer=setTimeout(()=>failPreview('官網畫面載入超過 20 秒，請重試；你仍可繼續修改。'),20000)}else sendPreview()}return r}catch(e:any){if(n!==sequence)return;fieldErrors.value=e.data?.data?.fieldErrors||[];if(show)failPreview(message(e));else error.value=message(e);await focusError()}
}
function showPreview(){mobile.value=window.innerWidth<768;previewOpen.value=true;void checkPreview(true);nextTick(()=>document.querySelector<HTMLElement>('.cms-effect-panel')?.scrollIntoView({block:'nearest'}))}
function closePreview(){previewOpen.value=false;sequence++;controller?.abort();clearTimeout(timer);clearTimeout(previewTimer);observer?.disconnect();previewReady.value=false;previewResult.value=null;initialToken.value='';previewError.value='';nextTick(()=>document.querySelector<HTMLElement>('.cms-savebar .cms-preview-button')?.focus())}
async function reloadPreview(manual=true){if(manual)recovery=0;needsReload=true;previewReady.value=false;await checkPreview(true)}
watch(bodies,()=>{if(!previewOpen.value)return;clearTimeout(timer);timer=setTimeout(()=>void checkPreview(true),400)},{deep:true})
watch(previewPath,()=>{if(previewResult.value){needsReload=true;void checkPreview(true)}})

const confirming=ref(false),confirmMode=ref('publish'),confirmation=ref<any>(),validating=ref(false)
async function save(action='save'){
 if(busy.value)return;busy.value=true;error.value='';notice.value=''
 try{const r=await api('page-editors/'+props.id,{method:'POST',body:payload(action),timeout:20000,retry:0});if(!Array.isArray(r?.documents)||r.documents.length!==docs.value.length||new Set(r.documents.map((d:any)=>d.id)).size!==docs.value.length||r.documents.some((d:any)=>!docs.value.some(x=>x.id===d.id)||!Number.isSafeInteger(d.revision)||!d.body||typeof d.body!=='object'||Array.isArray(d.body)))throw Error('伺服器未回傳完整儲存結果，請確認連線後重試；目前輸入仍保留。');for(const d of r.documents){bodies.value[d.id]=d.body;Object.assign(docs.value.find(x=>x.id===d.id),d)}baseline.value=JSON.parse(JSON.stringify(bodies.value));confirming.value=false;fieldErrors.value=[];notice.value=action==='publish'?'官網已更新。':action==='unpublish'?'已暫停本頁內容的官網顯示。':'本頁修改已儲存，官網尚未更新。';await refreshNuxtData(['cms-pages','cms-workspaces','cms-documents','cms-overview']);return true}catch(e:any){confirming.value=false;error.value=message(e);fieldErrors.value=e.data?.data?.fieldErrors||[];await focusError();return false}finally{busy.value=false}
}
async function requestSave(){if(!shared.value.length)return save();confirmMode.value='save';confirmation.value={documents:docs.value.map(d=>({id:d.id,title:resourceGuide(d.id)?.tabTitle||resourceGuide(d.id)?.location[0],changes:changedItems(baseline.value[d.id],bodies.value[d.id],editingSchema(d.schema,d.id))}))};confirming.value=true}
async function confirmPublish(){if(validating.value||busy.value)return;clearTimeout(timer);error.value='';validating.value=true;confirmMode.value='publish';try{const r=await checkPreview(false);if(r){confirmation.value=r;confirming.value=true}}finally{validating.value=false}}
async function unpublish(){if(window.confirm('暫停本頁內容會影響「會影響哪些頁面」列出的全部位置，包含共用內容；確定繼續？'))await save('unpublish')}
async function restore(d:any,version:string){if(dirty.value){error.value='請先儲存本頁修改，再取回以前的內容。';return}if(!window.confirm('這會將同份資料的完整舊版另存為草稿，可能包含其他區塊；官網不會立即改變。確定繼續？'))return;busy.value=true;try{await api('documents/'+d.id,{method:'POST',body:{action:'restore',revision:d.revision,version}});await load();notice.value='已取回以前的內容，確認後再更新官網。'}catch(e){error.value=message(e)}finally{busy.value=false}}
function beforeUnload(e:BeforeUnloadEvent){if(dirty.value){e.preventDefault();e.returnValue=''}}
watch(()=>props.id,load,{immediate:true})
onMounted(()=>{window.addEventListener('beforeunload',beforeUnload);window.addEventListener('message',receive)})
onBeforeUnmount(()=>{sequence++;controller?.abort();observer?.disconnect();clearTimeout(timer);clearTimeout(previewTimer);window.removeEventListener('beforeunload',beforeUnload);window.removeEventListener('message',receive)})
onBeforeRouteLeave(()=>!dirty.value||window.confirm('本頁還有尚未儲存的修改，確定離開？'))
onBeforeRouteUpdate((to,from)=>to.query.sitePage===from.query.sitePage||!dirty.value||window.confirm('本頁還有尚未儲存的修改，確定離開？'))
</script>
<template><section class="cms-page-editor cms-work-editor" :aria-busy="busy">
 <header class="cms-page-editor-heading"><NuxtLink :to="returnLink" class="cms-editor-breadcrumb">← 返回</NuxtLink><h1>{{ title }}</h1><AdminContentSearch /><a :href="active?.href||pageData?.href" target="_blank" rel="noopener noreferrer" class="cms-button">查看官網位置 ↗</a></header>
 <p v-if="error" class="cms-error" role="alert">{{ error }} <button type="button" class="cms-button" @click="reload">查看最新內容</button></p><p v-if="notice" class="cms-notice" role="status">{{ notice }}</p><p v-if="!pageData&&!error" class="cms-empty" role="status">正在載入頁面內容…</p>
 <template v-if="pageData"><button type="button" class="cms-button cms-location-toggle" :aria-expanded="locationOpen" @click="locationOpen=true">目前修改位置：{{ active?.name }} ▾</button>
 <div class="cms-page-edit-layout" :class="{'cms-preview-open':previewOpen}">
  <nav class="cms-block-nav cms-panel" aria-label="官網區塊"><button v-for="b in blocks.filter(b=>!b.secondary)" :key="b.id" type="button" :aria-current="active?.id===b.id?'location':undefined" @click="selectBlock(b.id)"><AdminImage v-if="blockThumbnail(b,bodies)" :src="blockThumbnail(b,bodies)" :alt="b.name+'區塊縮圖'" /><span>{{ b.name }}</span><small v-if="modified.some(m=>m.id===b.id)" aria-label="尚未儲存">●</small></button><details v-if="blocks.some(b=>b.secondary)"><summary>其他設定</summary><button v-for="b in blocks.filter(b=>b.secondary)" :key="b.id" type="button" @click="selectBlock(b.id)">{{ b.name }}</button></details></nav>
  <div ref="formRoot" class="cms-page-form"><div class="cms-panel cms-block-form"><div class="cms-block-heading"><h2 class="cms-block-title" tabindex="-1">{{ active?.name }}</h2><button v-if="previewOpen" type="button" class="cms-button" @click="locationOpen=true">換修改位置</button></div><fieldset :disabled="busy" class="cms-edit-form"><div v-for="f in active?.fields||[]" :key="f.documentId+':'+f.path" :class="['cms-block-field',{'cms-block-field-long':typeof valueAt(bodies[f.documentId],f.path)==='string'&&valueAt(bodies[f.documentId],f.path).length>80}]"><AdminFields :model-value="valueAt(bodies[f.documentId],f.path)" :schema="f.schema" :label="f.path.split('.').at(-1)" :document-id="f.documentId" :path="f.path" @update:model-value="update(f,$event)" /></div></fieldset></div>
   <details class="cms-panel cms-secondary"><summary>會影響哪些頁面（{{ impacts.length }}）</summary><ul><li v-for="i in impacts" :key="i.href+i.label"><a :href="i.href" target="_blank" rel="noopener noreferrer">{{ i.label }} ↗</a></li></ul></details>
   <details class="cms-panel cms-secondary"><summary>過去的修改</summary><section v-for="d in activeDocs" :key="d.id"><h3>{{ resourceGuide(d.id)?.tabTitle||resourceGuide(d.id)?.location[0] }}</h3><div v-for="v in d.versions" :key="v.id" class="cms-history-row"><span>{{ cmsDate(v.createdAt) }} · {{ v.actor||'初始內容' }}</span><button v-if="session?.role==='admin'" type="button" class="cms-button" :disabled="busy||dirty" @click="restore(d,v.id)">取回這份內容</button></div></section></details>
  </div>
  <aside v-if="previewOpen" class="cms-effect-panel cms-panel" aria-label="官網效果"><div class="cms-effect-toolbar"><strong>官網效果</strong><button type="button" class="cms-button" @click="mobile=!mobile">{{ mobile?'看桌機':'看手機' }}</button><button type="button" class="cms-button" @click="reloadPreview()">重試</button><button type="button" class="cms-button" @click="closePreview">返回修改</button></div><select v-if="choices.length" v-model="previewPath" aria-label="選擇預覽頁面"><option value="">目前頁面</option><option v-for="p in choices" :key="p.path" :value="p.path">{{ p.label }}</option></select><p class="cms-field-help" role="status">{{ previewState }}</p><p v-if="previewError" class="cms-error" role="alert">{{ previewError }} <a v-if="previewResult&&initialToken" :href="previewUrl" target="_blank" rel="noopener noreferrer" class="cms-button">另開效果畫面 ↗</a></p><div class="cms-effect-viewport" :class="{'cms-effect-mobile':mobile}"><iframe v-if="previewResult" :key="initialToken" ref="previewFrame" :style="frameStyle" :src="previewUrl" title="目前輸入的官網效果" @error="failPreview('預覽載入失敗，請重試；目前輸入仍保留。')" /></div></aside>
 </div>
 <footer class="cms-savebar" aria-label="目前內容操作"><span class="cms-save-status" role="status">{{ status }}</span><div class="cms-actions"><details v-if="session?.role==='admin'" class="cms-more-actions"><summary class="cms-button">更多操作</summary><div><button type="button" class="cms-button" :disabled="busy||dirty||!docs.some(d=>d.publishedId)" @click="unpublish">暫停官網顯示</button></div></details><button type="button" class="cms-button cms-preview-button" :disabled="busy" @click="previewOpen?closePreview():showPreview()">{{ previewOpen?'關閉效果':'看效果' }}</button><button type="button" class="cms-button" :class="{'cms-button-gold':dirty}" :disabled="busy||!dirty" @click="requestSave">{{ busy?'處理中…':'儲存' }}</button><button v-if="session?.role==='admin'" type="button" class="cms-button" :class="{'cms-button-gold':!dirty}" :disabled="busy||validating||(!dirty&&!pending)" @click="confirmPublish">{{ validating?'正在確認…':'更新官網' }}</button></div></footer>
 </template>
 <AdminDialog :open="locationOpen" title="選擇要修改的位置" @close="locationOpen=false"><nav class="cms-block-nav cms-block-picker" aria-label="選擇官網區塊"><button v-for="b in blocks" :key="b.id" type="button" :aria-current="active?.id===b.id?'location':undefined" @click="selectBlock(b.id)"><AdminImage v-if="blockThumbnail(b,bodies)" :src="blockThumbnail(b,bodies)" :alt="b.name+'縮圖'" /><span>{{ b.name }}</span></button></nav></AdminDialog>
 <AdminDialog :open="confirming" :title="confirmMode==='save'?'這些位置會共用本次修改':'確認要更新到官網的內容'" @close="confirming=false"><p>{{ confirmMode==='save'?'儲存後不會立即更新官網。':'包含同份資料中其他已儲存、尚未更新到官網的修改：' }}</p><section v-for="d in confirmation?.documents?.filter((d:any)=>d.changes.length)||[]" :key="d.id"><h3>{{ d.title }}</h3><ul><li v-for="(c,i) in d.changes" :key="i">{{ c }}</li></ul></section><details open><summary>會影響的位置</summary><ul><li v-for="i in confirmMode==='save'?shared:impacts" :key="i.href+i.label">{{ i.label }}</li></ul></details><p v-if="error" class="cms-error" role="alert">{{ error }}</p><div class="cms-actions"><button type="button" class="cms-button" :disabled="busy" @click="confirming=false">返回修改</button><button type="button" class="cms-button cms-button-gold" :disabled="busy" @click="save(confirmMode)">{{ busy?'處理中…':confirmMode==='save'?'確認儲存':'確認更新官網' }}</button></div></AdminDialog>
</section></template>
